16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^(\\+[0-9]{8,15}|[0-9]{10})$",
49	        message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "membership_number")
62	    private String membershipNumber;
63	
64	    @Column(name = "household_id")
65	    private String householdId;
66	
67	    @Column(name = "namesake_count")
68	    private Integer namesakeCount;
69	
70	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
71	    private Set<Pet> pets;
72	
73	    public String getAddress() {
74	        return this.address;
75	    }
76	
77	    public void setAddress(String address) {
78	        this.address = address;
79	    }
80	
81	    public String getCity() {
82	        return this.city;
83	    }
84	
85	    public void setCity(String city) {
86	        this.city = city;
87	    }
88	
89	    public String getTelephone() {
90	        return this.telephone;
91	    }
92	
93	    public void setTelephone(String telephone) {
94	        this.telephone = telephone;
95	    }
96	
97	    public String getEmail() {
98	        return this.email;
99	    }
100	
101	    public void setEmail(String email) {
102	        this.email = email;
103	    }
104	
105	    public LocalDate getRegistrationDate() {
106	        return this.registrationDate;
107	    }
108	
109	    public void setRegistrationDate(LocalDate registrationDate) {
110	        this.registrationDate = registrationDate;
111	    }
112	
113	    public String getCustomerCode() {
114	        return this.customerCode;
115	    }
116	
117	    public void setCustomerCode(String customerCode) {
118	        this.customerCode = customerCode;
119	    }
120	
121	    public String getMembershipNumber() {
122	        return this.membershipNumber;
123	    }
124	
125	    public void setMembershipNumber(String membershipNumber) {
126	        this.membershipNumber = membershipNumber;
127	    }
128	
129	    public String getHouseholdId() {
130	        return this.householdId;
131	    }
132	
133	    public void setHouseholdId(String householdId) {
134	        this.householdId = householdId;
135	    }
136	
137	    public Integer getNamesakeCount() {
138	        return this.namesakeCount;
139	    }
140	
141	    public void setNamesakeCount(Integer namesakeCount) {
142	        this.namesakeCount = namesakeCount;
143	    }
144	
145	    protected Set<Pet> getPetsInternal() {
146	        if (this.pets == null) {
147	            this.pets = new HashSet<>();
148	        }
149	        return this.pets;
150	    }
151	
152	    protected void setPetsInternal(Set<Pet> pets) {
153	        this.pets = pets;
154	    }
155	
156	    public List<Pet> getPets() {
157	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
158	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
159	        return Collections.unmodifiableList(sortedPets);
160	    }
161	
162	    public void setPets(List<Pet> pets) {
163	        this.pets = new HashSet<>(pets);
164	    }
165	
166	    public void addPet(Pet pet) {
167	        getPetsInternal().add(pet);
168	        pet.setOwner(this);
169	    }
170	
171	    /**
172	     * Return the Pet with the given name, or null if none found for this Owner.
173	     *
174	     * @param name to test
175	     * @return true if pet name is already in use
176	     */
177	    public Pet getPet(String name) {
178	        return getPet(name, false);
179	    }
180	
181	    /**
182	     * Return the Pet with the given name, or null if none found for this Owner.
183	     *
184	     * @param name to test
185	     * @return true if pet name is already in use
186	     */
187	    public Pet getPet(String name, boolean ignoreNew) {
188	        name = name.toLowerCase();
189	        for (Pet pet : getPetsInternal()) {
190	            if (!ignoreNew || !pet.isNew()) {
191	                String compName = pet.getName();
192	                compName = compName.toLowerCase();
193	                if (compName.equals(name)) {
194	                    return pet;
195	                }
196	            }
197	        }
198	        return null;
199	    }
200	
201	    public Pet getPet(Integer petId) {
202	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
203	    }
204	
205	    @Override
206	    public String toString() {
207	        return new ToStringCreator(this)
208	
209	            .append("id", this.getId())
210	            .append("new", this.isNew())
211	            .append("lastName", this.getLastName())
212	            .append("firstName", this.getFirstName())
213	            .append("address", this.address)
214	            .append("city", this.city)
215	            .append("telephone", this.telephone)
216	            .toString();
217	    }
218	}
