31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Dedicated audit logger; each successful owner create emits one line here. */
66	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
109	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
110	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String address = normalizeAddress(owner.getAddress());
119	        if (address.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setAddress(address);
123	        String telephone = toE164(owner.getTelephone());
124	        if (telephone == null) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        if (owner.getEmail() != null) {
128	            String email = normalizeEmail(owner.getEmail());
129	            if (email == null) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	        }
134	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
135	        if (effectiveRegistrationDate == null) {
136	            effectiveRegistrationDate = LocalDate.now();
137	        }
138	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
139	        owner.setRegistrationDate(registrationDate);
140	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
144	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
145	        }
146	        for (Owner existing : this.clinicService.findAllOwners()) {
147	            if (telephone.equals(toE164(existing.getTelephone()))) {
148	                return new ResponseEntity<>(HttpStatus.CONFLICT);
149	            }
150	        }
151	        String lastNameKey = householdKey(owner.getLastName());
152	        String addressKey = householdKey(owner.getAddress());
153	        List<Owner> householdMembers = new ArrayList<>();
154	        for (Owner existing : this.clinicService.findAllOwners()) {
155	            if (lastNameKey.equals(householdKey(existing.getLastName()))
156	                && addressKey.equals(householdKey(existing.getAddress()))) {
157	                householdMembers.add(existing);
158	            }
159	        }
160	        if (!householdMembers.isEmpty()) {
161	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
162	                return new ResponseEntity<>(HttpStatus.CONFLICT);
163	            }
164	            String householdId = householdId(lastNameKey, addressKey);
165	            owner.setHouseholdId(householdId);
166	            for (Owner member : householdMembers) {
167	                if (!householdId.equals(member.getHouseholdId())) {
168	                    member.setHouseholdId(householdId);
169	                    this.clinicService.saveOwner(member);
170	                }
171	            }
172	        }
173	        owner.setTelephone(telephone);
174	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
175	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
176	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
177	        this.clinicService.saveOwner(owner);
178	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
179	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
180	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
181	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
182	        headers.setLocation(UriComponentsBuilder.newInstance()
183	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
184	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        currentOwner.setAddress(ownerFieldsDto.getAddress());
195	        currentOwner.setCity(ownerFieldsDto.getCity());
196	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
197	        currentOwner.setLastName(ownerFieldsDto.getLastName());
198	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
199	        this.clinicService.saveOwner(currentOwner);
200	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Transactional
205	    @Override
206	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner == null) {
209	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
210	        }
211	        this.clinicService.deleteOwner(owner);
212	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner == null) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        HttpHeaders headers = new HttpHeaders();
223	        Pet pet = petMapper.toPet(petFieldsDto);
224	        owner.setId(ownerId);
225	        pet.setOwner(owner);
226	        pet.getType().setName(null);
227	        this.clinicService.savePet(pet);
228	        PetDto petDto = petMapper.toPetDto(pet);
229	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
230	            .buildAndExpand(pet.getId()).toUri());
231	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
232	    }
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
237	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
238	        if (currentOwner != null) {
239	            Pet currentPet = this.clinicService.findPetById(petId);
240	            if (currentPet != null) {
241	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
242	                currentPet.setName(petFieldsDto.getName());
243	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
244	                this.clinicService.savePet(currentPet);
245	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
246	            }
247	        }
248	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	    }
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
254	        HttpHeaders headers = new HttpHeaders();
255	        Visit visit = visitMapper.toVisit(visitFieldsDto);
256	        Pet pet = new Pet();
257	        pet.setId(petId);
258	        visit.setPet(pet);
259	        this.clinicService.saveVisit(visit);
260	        VisitDto visitDto = visitMapper.toVisitDto(visit);
261	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
262	            .buildAndExpand(visit.getId()).toUri());
263	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
264	    }
265	
266	
267	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
268	    @Override
269	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
270	        Owner owner = this.clinicService.findOwnerById(ownerId);
271	        if (owner != null) {
272	            Pet pet = owner.getPet(petId);
273	            if (pet != null) {
274	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
275	            }
276	        }
277	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
278	    }
279	
280	    /**
281	     * The maximum number of owners permitted per city. Owner creation is rejected once the
282	     * owner's city already contains this many owners.
283	     */
284	    private static final int MAX_OWNERS_PER_CITY = 50;
285	
286	    /**
287	     * Counts how many existing owners live in the given city, compared case-insensitively.
288	     * This is evaluated before the new owner is persisted, so the owner being created is not
289	     * included in the count.
290	     *
291	     * @param city the new owner's city
292	     * @return the number of existing owners in that city
293	     */
294	    private int countOwnersInCity(String city) {
295	        int count = 0;
296	        for (Owner existing : this.clinicService.findAllOwners()) {
297	            if (city.equalsIgnoreCase(existing.getCity())) {
298	                count++;
299	            }
300	        }
301	        return count;
302	    }
303	
304	    /**
305	     * The maximum number of owners that may be created in a single business day. Owner
306	     * creation is rejected once this many owners already fall on the new owner's adjusted
307	     * business day {@code registrationDate}.
308	     */
309	    private static final int MAX_OWNERS_PER_DAY = 100;
310	
311	    /**
312	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
313	     * to the following Monday, while a weekday is returned unchanged.
314	     *
315	     * @param date the date to adjust
316	     * @return the same date if it is a weekday, otherwise the following Monday
317	     */
318	    private LocalDate toBusinessDay(LocalDate date) {
319	        DayOfWeek dayOfWeek = date.getDayOfWeek();
320	        if (dayOfWeek == DayOfWeek.SATURDAY) {
321	            return date.plusDays(2);
322	        }
323	        if (dayOfWeek == DayOfWeek.SUNDAY) {
324	            return date.plusDays(1);
325	        }
326	        return date;
327	    }
328	
329	    /**
330	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
331	     * registrationDate} rolls forward to the same business day. This is evaluated before the
332	     * new owner is persisted, so the owner being created is not included in the count.
333	     *
334	     * @param businessDay the adjusted business day to count against
335	     * @return the number of existing owners registered on that business day
336	     */
337	    private int countOwnersRegisteredOn(LocalDate businessDay) {
338	        int count = 0;
339	        for (Owner existing : this.clinicService.findAllOwners()) {
340	            LocalDate existingDate = existing.getRegistrationDate();
341	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
342	                count++;
343	            }
344	        }
345	        return count;
346	    }
347	
348	    /**
349	     * The number of owners that may be created on a single business day before a bulk-signup
350	     * warning is raised. Once more than this many owners already fall on the current business
351	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
352	     */
353	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
354	
355	    /**
356	     * Reports whether an unusually high number of owners have been created for today's business
357	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
358	     * the business day that {@code LocalDate.now()} rolls forward to.
359	     *
360	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
361	     */
362	    private boolean isBulkSignupDay() {
363	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
364	    }
365	
366	    /**
367	     * Builds the customer code for a newly created owner, formatted
368	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
369	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
370	     * the last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal
371	     * to one more than the number of owners already in that city.
372	     *
373	     * @param city     the owner's city
374	     * @param lastName the owner's last name
375	     * @return the assigned customer code (e.g. {@code 'SYD-SMI-0007'})
376	     */
377	    private String nextCustomerCode(String city, String lastName) {
378	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
379	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
380	        int sequence = 1;
381	        for (Owner existing : this.clinicService.findAllOwners()) {
382	            if (city.equalsIgnoreCase(existing.getCity())) {
383	                sequence++;
384	            }
385	        }
386	        return String.format("%s-%s-%04d", city3, last3, sequence);
387	    }
388	
389	    /**
390	     * Builds the membership number for a newly created owner, formatted
391	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
392	     * customer code and {@code YY} is the last two digits of the owner's registration
393	     * date year, zero-padded to two digits.
394	     *
395	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SYD-SMI-0007'})
396	     * @param registrationDate the owner's registration date
397	     * @return the assigned membership number (e.g. {@code 'SYD-SMI-0007-M26'})
398	     */
399	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
400	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
401	    }
402	
403	    /**
404	     * Counts how many existing owners share the given first and last name, compared
405	     * case-insensitively. This is evaluated before the new owner is persisted, so the
406	     * owner being created is not included in the count.
407	     *
408	     * @param firstName the new owner's first name
409	     * @param lastName  the new owner's last name
410	     * @return the number of existing owners with the same first and last name
411	     */
412	    private int countNamesakes(String firstName, String lastName) {
413	        int count = 0;
414	        for (Owner existing : this.clinicService.findAllOwners()) {
415	            if (firstName.equalsIgnoreCase(existing.getFirstName())
416	                && lastName.equalsIgnoreCase(existing.getLastName())) {
417	                count++;
418	            }
419	        }
420	        return count;
421	    }
422	
423	    /**
424	     * Canonical expansions applied to common street-type abbreviations during address
425	     * normalization. Keys and values are upper-cased so the lookup runs after the address
426	     * has itself been upper-cased.
427	     */
428	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
429	        "ST", "STREET",
430	        "RD", "ROAD",
431	        "AVE", "AVENUE");
432	
433	    /**
434	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
435	     * every run of internal whitespace is collapsed to a single space, the result is
436	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
437	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
438	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
439	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
440	     * returned and compared for household duplicates; an address that is blank once
441	     * normalized fails the required-field check.
442	     *
443	     * @param address the raw address value supplied by the client
444	     * @return the normalized address (empty string when {@code address} is null or blank)
445	     */
446	    private static String normalizeAddress(String address) {
447	        if (address == null) {
448	            return "";
449	        }
450	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
451	        if (collapsed.isEmpty()) {
452	            return "";
453	        }
454	        StringBuilder normalized = new StringBuilder(collapsed.length());
455	        for (String token : collapsed.split(" ")) {
456	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
457	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
458	            if (normalized.length() > 0) {
459	                normalized.append(' ');
460	            }
461	            normalized.append(expanded != null ? expanded : token);
462	        }
463	        return normalized.toString();
464	    }
465	
466	    /**
467	     * Normalizes a last name or address for household-duplicate comparison: leading and
468	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
469	     * single space and the result is lower-cased. Two owners are considered to share a
470	     * household when both their last names and addresses produce the same key.
471	     *
472	     * @param value the raw last name or address value
473	     * @return the normalized comparison key (empty string when {@code value} is null)
474	     */
475	    private static String householdKey(String value) {
476	        if (value == null) {
477	            return "";
478	        }
479	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
480	    }
481	
482	    /**
483	     * Derives the stable shared household identifier for the given normalized last name
484	     * and address keys. The identifier is deterministic — the same household (same
485	     * {@link #householdKey normalized} last name and address) always maps to the same
486	     * value — so every owner who joins a household is assigned an identical id. It is the
487	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
488	     * '<lastNameKey>|<addressKey>'}.
489	     *
490	     * @param lastNameKey the normalized last name key
491	     * @param addressKey  the normalized address key
492	     * @return the shared household identifier
493	     */
494	    private static String householdId(String lastNameKey, String addressKey) {
495	        String source = lastNameKey + "|" + addressKey;
496	        try {
497	            byte[] digest = MessageDigest.getInstance("SHA-256")
498	                .digest(source.getBytes(StandardCharsets.UTF_8));
499	            StringBuilder hex = new StringBuilder(digest.length * 2);
500	            for (byte b : digest) {
501	                hex.append(String.format("%02x", b));
502	            }
503	            return hex.substring(0, 12).toUpperCase();
504	        } catch (NoSuchAlgorithmException e) {
505	            throw new IllegalStateException("SHA-256 not available", e);
506	        }
507	    }
508	
509	    /**
510	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
511	     * and brackets are stripped. When the number already carries a leading {@code '+'}
512	     * and country code these are kept; otherwise Australia's country code {@code '+61'}
513	     * is assumed and a single leading {@code '0'} is dropped from the national digits.
514	     * The resulting number must have between 8 and 15 digits after the {@code '+'}.
515	     *
516	     * @param telephone the raw telephone value supplied by the client
517	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
518	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
519	     */
520	    private static String toE164(String telephone) {
521	        if (telephone == null) {
522	            return null;
523	        }
524	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
525	        String digits;
526	        if (cleaned.startsWith("+")) {
527	            digits = cleaned.substring(1);
528	        } else {
529	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
530	            digits = "61" + national;
531	        }
532	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
533	    }
534	
535	    /**
536	     * Normalizes an owner email for creation. A present email must be a syntactically
537	     * valid address; the returned value is lower-cased.
538	     *
539	     * @param email the raw email value supplied by the client (never {@code null} here)
540	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
541	     *         address (signalling a 400 Bad Request)
542	     */
543	    private static String normalizeEmail(String email) {
544	        String trimmed = email.trim();
545	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
546	            return null;
547	        }
548	        return trimmed.toLowerCase();
549	    }
550	}
